IF @params<>4 OR @active<>1
BEGIN
 RAISERROR(N'DSL05_PLAN_GUARD: the plan writer or the owner principal is not as reviewed; nothing was recorded.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
